import { Context } from "effect";
import { MediaClient } from "./media-client.js";
export class ImageClientService extends Context.Service()("@opencode/ImageClient") {
}
export const Service = ImageClientService;
export const ImageClient = {
    Service,
    ...MediaClient.make(Service, {
        modality: "image",
        responseEvents: (response) => [
            ...response.images.map((image, index) => ({ type: "image", index, image })),
            { type: "finish", usage: response.usage, providerMetadata: response.providerMetadata },
        ],
    }),
};
